input.command:
cat > bin/rotate <<'EOF'
#!/bin/bash
# Usage: rotate <log dir> <archive dir> <name> <stamp YYYYMMDD>
root=$(cd "$(dirname "$0")/.." && pwd)
. "$root/lib/local.sh"
. "$root/lib/archive.sh"
. "$root/lib/prune.sh"
rotate_local "$1" "$3"
archive_copy "$1" "$2" "$3" "$4"
keep=$(read_keep "$root/config/rotate.conf") || { echo "rotate: invalid keep, skip pruning" >&2; exit 0; }
prune_local "$1" "$3" "$keep"
prune_archive "$2" "$3" "$keep"
EOF
cat > tests/rotate_test.sh <<'EOF'
#!/bin/bash
fail=0
d=$(mktemp -d)
mkdir -p "$d/logs"
echo one > "$d/logs/app.log"; bash bin/rotate "$d/logs" "$d/archive" app.log 20261001
echo two > "$d/logs/app.log"; bash bin/rotate "$d/logs" "$d/archive" app.log 20261002
[ "$(cat "$d/logs/app.log.1")" = two ] || { echo "app.log.1"; fail=1; }
[ "$(cat "$d/logs/app.log.2")" = one ] || { echo "app.log.2"; fail=1; }
[ "$(cat "$d/archive/app.log.20261002")" = two ] || { echo "archive"; fail=1; }
# LOG-31: keep=3 -> older generations pruned, locally and in archive
echo other > "$d/logs/other.log.9"; echo o > "$d/archive/other.log.20200101"
for i in 3 4 5 6; do echo "g$i" > "$d/logs/app.log"; bash bin/rotate "$d/logs" "$d/archive" app.log 2026100$i; done
[ "$(ls "$d/logs" | grep -c '^app\.log\.[0-9]')" = 3 ] || { echo "local keep"; fail=1; }
[ -e "$d/logs/app.log.4" ] && { echo "local app.log.4 remains"; fail=1; }
[ "$(ls "$d/archive" | grep -c '^app\.log\.')" = 3 ] || { echo "archive keep"; fail=1; }
[ -e "$d/archive/app.log.20261003" ] && { echo "oldest archive remains"; fail=1; }
[ -e "$d/archive/app.log.20261006" ] || { echo "newest archive missing"; fail=1; }
[ -e "$d/logs/other.log.9" ] && [ -e "$d/archive/other.log.20200101" ] || { echo "other name touched"; fail=1; }
rm -rf "$d"
exit $fail
EOF
bash scripts/verify.sh; echo rc=$?
git stash -q -- bin/rotate; bash tests/rotate_test.sh; echo "before-fix rc=$?"; git stash pop -q; git status --short
